activationBar102=function(){const m=member10();if(m.active)return '';const pending=m.application?.status==='pending',identity=!!m.identity.document&&!!m.identity.person&&!!m.identity.location?.complete;return `<section class="activation102 activation105"><div><strong>${pending?L105('Akun sedang diperiksa','Account under review'):L105('Aktivasi akun','Account activation')}</strong><div class="activation-track102">${[[L105('Identitas Label','Label Identity'),identity],[L105('Kontrak','Agreement'),m.contract],[L105('Pemeriksaan','Review'),pending]].map(([text,done],i)=>`<span class="${done?'done':''}"><i>${done?'✓':i+1}</i>${text}</span>`).join('')}</div></div><button class="btn primary" data-onboard105="activation">${pending?L105('Lihat Status','View Status'):L105('Lanjutkan','Continue')}</button></section>`;};
activationPopup102=function(){if(!isLabel10())return;const m=member10();onboarding105.active=true;if(m.application?.status==='pending'){reviewDialogUI(L105('Akun sedang diperiksa','Account under review'),`${language105()}<div class="welcome105"><span class="review-orbit105"></span><h2>${E(m.name)}</h2><p>${L105('Identitas dan persetujuan kontrak sudah diterima. Hasil pemeriksaan akan tampil di dashboard.','Your identity and agreement have been received. Review results will appear on your dashboard.')}</p><p>${L105('Masa langganan dimulai setelah akun labelmu aktif.','Your subscription starts once your label account is active.')}</p><button class="btn" data-onboard105="bank">${L105('Lengkapi Rekening','Add Payout Account')}</button><button class="btn primary" data-onboard105="finish">${L105('Buka Dashboard','Open Dashboard')}</button></div>`);return;}activationStep105();};
function activationStep105(){const m=member10(),values=m.onboardingDraft105||{name:m.name,email:m.email,person:m.identity.person,...m.identity};ensureContracts102();const c=ten.contracts102.at(-1);let html='';
 if(onboarding105.step===1)html=`<form class="ten-form activation-form105" data-onboard-form105="identity">${field10('name',L105('Nama label','Label name')+' <i class="required105">*</i>',values.name||'','text','required')}${field10('email','Email <i class="required105">*</i>',values.email||m.email,'email','required')}${field10('person',L105('Penanggung jawab','Representative')+' <i class="required105">*</i>',values.person||'','text','required')}${directoryLocationFields({...m.identity,...values})}<div class="identity-upload105"><strong>KTP <i class="required105">*</i></strong><small>${m.identity.document?L105('Dokumen sudah tersedia','Document available'):L105('Dokumen penanggung jawab diperlukan','Representative document required')}</small><button class="btn" type="button" data-onboard105="document">${m.identity.document?L105('Ganti / sesuaikan foto KTP','Replace / adjust identity photo'):L105('Unggah foto KTP','Upload identity photo')}</button></div><footer class="full"><button class="btn primary" type="submit">${L105('Lanjutkan','Next')} →</button></footer></form>`;
 else html=`<form data-onboard-form105="contract"><div class="contract-text102"><h3>${E(ten.lang==='en'?c.titleEn:c.title)}</h3><p>${E(ten.lang==='en'?c.bodyEn:c.body)}</p></div>${info10('contract105','Dokumen ini adalah naskah contoh untuk menguji persetujuan. Kontrak final mengikuti dokumen yang diterbitkan Rilis Musik.','This sample document tests the consent flow. Final terms follow the agreement published by Rilis Musik.')}<label class="check105"><input name="agree" type="checkbox" required>${L105('Saya telah membaca dan menyetujui kontrak ini.','I have read and agree to this contract.')}</label><p>${L105('Masa langganan dimulai setelah akun labelmu aktif.','Your subscription starts once your label account is active.')}</p><footer class="activation-actions105"><button type="button" class="btn text" data-onboard105="identity-back">← ${L105('Identitas','Identity')}</button><button type="submit" name="next" value="later" class="btn">${L105('Kirim dan Lanjutkan Nanti','Submit and Continue Later')}</button><button type="submit" name="next" value="bank" class="btn primary">${L105('Lanjutkan ke Rekening','Continue to Payout Account')} →</button></footer></form>`;
 reviewDialogUI(L105('Aktivasi akun','Account activation'),`${language105()}<div class="activation-steps105"><span class="${onboarding105.step===1?'active':''}">01 · ${L105('Identitas Label','Label Identity')}</span><span class="${onboarding105.step===2?'active':''}">02 · ${L105('Kontrak','Agreement')}</span></div>${m.application?.status==='correction'?`<div class="correction-note105">${E(m.application.note)}</div>`:''}${html}`);const f=document.querySelector('[data-onboard-form105=identity]');if(f){directoryRefresh(f,null);for(const input of f.querySelectorAll('[required]')){const label=input.closest('label');if(label&&!label.querySelector('.required105'))label.insertAdjacentHTML('afterbegin','<i class="required105">*</i>');}for(const label of f.querySelectorAll('label')){const star=label.querySelector(':scope > .required105');if(!star)continue;const title=document.createElement('span');for(const n of [...label.childNodes])if(n.nodeType===3&&n.textContent.trim())title.append(n);title.append(' ',star);label.prepend(title);}}
}
function captureIdentity105(strict=false){const f=document.querySelector('[data-onboard-form105=identity]');if(!f)return;const m=member10(),v=Object.fromEntries(new FormData(f));const identity=directoryIdentity(v,strict,m.identity);m.onboardingDraft105={...v,...identity};save10();return {name:v.name.trim(),email:v.email.trim().toLowerCase(),identity};}
function submittedActivation105(){onboarding105.active=false;reviewDialogUI('',`${language105()}<div class="welcome105"><span class="welcome-spark105">✓</span><h1>${E(member10().name)}</h1><h2>${L105('Pengajuan aktivasi diterima.','Activation application received.')}</h2><p>${L105('Kami akan memeriksa identitas labelmu. Perkembangannya tersedia di dashboard.','We will review your label identity. Follow the progress on your dashboard.')}</p><button class="btn primary" data-onboard105="theme">${L105('Lanjutkan','Continue')}</button></div>`);}
function claimStart105(){reviewDialogUI(L105('Klaim Label','Claim Label'),`${language105()}<form data-onboard-form105="claim-search"><p>${L105('Masukkan nama label atau email yang digunakan saat bekerja sama.','Enter the label name or email used in your existing partnership.')}</p>${field10('lookup',L105('Nama label atau email lama','Label name or previous email'),'','text','required')}<button class="btn primary" type="submit">${L105('Cari Label','Find Label')}</button></form>${info10('claim105','Jalur klaim ini adalah rancangan sementara untuk dibahas bersama tim. Tidak ada email atau pesan yang dikirim dari prototype.','This provisional claim flow will be reviewed with the team. This prototype sends no email or messages.')}`);}
function claimResult105(m){ten.claimDraft105={member:m.id,applicant:ten.member};reviewDialogUI(L105('Konfirmasi hubungan label','Confirm your label connection'),`${language105()}<h2>${E(m.name)}</h2><p>${L105('Konfirmasi melalui kontak lama yang tercatat.','Confirm using the existing contact on record.')}</p><strong>${E(m.email.slice(0,2))}•••@${E(m.email.split('@')[1]||'•••')}</strong><form data-onboard-form105="claim-code">${field10('code',L105('Kode konfirmasi','Confirmation code'),'','text','required inputmode="numeric"')}<button class="btn primary">${L105('Ajukan Klaim','Submit Claim')}</button></form><button class="btn text" data-onboard105="claim-recovery">${L105('Kontak lama tidak dapat diakses','I cannot access the previous contact')}</button>${info10('claim-code105','Untuk mencoba alur lokal gunakan kode 123456. Kode produksi harus dikirim dan diperiksa melalui server.','For this local preview use code 123456. Production codes must be delivered and verified by a server.')}`);}
window.addEventListener('click',async e=>{const b=e.target.closest('[data-onboard105]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const a=b.dataset.onboard105,m=member10();try{
 if(a==='language')return switchLanguage120(b.dataset.id);
 if(a==='new'){m.onboardingSeen105=true;m.name=m.name==='Embun Label'?'':m.name;save10();welcomeExplore105();return;}
 if(a==='explore'){m.onboardingSeen105=true;save10();themeDialog105(true);return;}
 if(a==='claim')return claimStart105();if(a==='activation')return activationPopup102();if(a==='identity-back'){onboarding105.step=1;return activationStep105();}
 if(a==='document'){captureIdentity105(false);onboarding105.document=true;return document10();}
 if(a==='theme')return themeDialog105(true);
 if(a==='active-welcome'){m.welcome=true;save10();closeModal();return render();}
 if(a==='finish'){onboarding105.active=false;closeModal();state.page='dashboard';return render();}
 if(a==='bank'){onboarding105.active=false;ui103.profileTab='bank';route102('account');closeModal();return;}
 if(a==='claim-recovery')return claimRecovery105();
 if(a==='claim-approve'||a==='claim-correct')return reviewClaim120(a,b.dataset.id,b.dataset.version);
 }catch(err){toast(err.message);}},true);
window.addEventListener('input',e=>{if(e.target.closest('[data-onboard-form105=identity]')){clearTimeout(onboarding105.timer);onboarding105.timer=setTimeout(()=>captureIdentity105(false),400);}});
window.addEventListener('submit',e=>{const f=e.target,k=f.dataset.onboardForm105;if(!k)return;e.preventDefault();e.stopImmediatePropagation();if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f)),m=member10();try{
 if(k==='identity'){const p=captureIdentity105(true);if(!m.identity.document)throw Error('identity');RM10.act(ten,'profile',p);delete m.onboardingDraft105;save10();onboarding105.step=2;return activationStep105();}
 if(k==='contract'){if(!m.paid){toast(L105('Choisis un crédit ou un forfait pour continuer.','Purchase credits or a plan to continue.').replace('Choisis un crédit ou un forfait pour continuer.','Beli kredit atau paket untuk melanjutkan.'));return purchase10();}RM10.act(ten,'contract');acceptContract102(m);RM10.act(ten,'apply');save10();onboarding105.active=false;if(e.submitter?.value==='bank'){reviewDialogUI(L105('Rekening Penerima · opsional','Payout Account · optional'),bankForm10(m)+`<button class="btn text" data-onboard105="theme">${L105('Lengkapi Nanti','Complete Later')}</button>`);onboarding105.bank=true;return;}return submittedActivation105();}
 if(k==='claim-search'){const found=ten.members.find(x=>x.id!==m.id&&(x.name.toLowerCase()===v.lookup.trim().toLowerCase()||x.email.toLowerCase()===v.lookup.trim().toLowerCase()));if(!found){toast(L105('Label belum ditemukan. Periksa nama atau email yang digunakan.','Label not found. Check the name or email.'));return;}return claimResult105(found);}
 if(k==='claim-code'||k==='claim-recovery'){if(k==='claim-code'&&v.code!=='123456')throw Error('Kode belum sesuai. Periksa kembali.');const q=ten.claimDraft105;if(!q||q.applicant!==m.id)throw Error('state');ten.claims105??=[];if(ten.claims105.some(x=>x.applicant===m.id&&x.member===q.member&&x.status==='pending'))throw Error('pending');ten.claims105.unshift({...q,id:'CLAIM-'+(++ten.serial),status:'pending',recovery:k==='claim-recovery',note:v.note||'',at:ten.now});m.onboardingSeen105=true;save10();reviewDialogUI(L105('Klaim sedang diperiksa','Claim under review'),`<p>${L105('Akses label diberikan setelah hubungan kepemilikan disetujui.','Label access is granted after ownership is approved.')}</p><button class="btn primary" data-onboard105="finish">${L105('Buka Dashboard','Open Dashboard')}</button>`);return;}
 if(k==='claim-correct')return correctClaim120(f,v);
 }catch(err){if(k==='claim-correct')saveError117(f,err);else toast(error105(err.message));}},true);
const labelsBefore105=labels102;labels102=function(){const html=labelsBefore105(),qs=(ten.claims105||[]).filter(q=>q.status==='pending');return html+(ten.role==='super'&&qs.length?`<section class="panel pad"><h2>${L105('Klaim Label','Label Claims')}</h2>${qs.map(q=>`<article class="approval-row-ui"><div><strong>${E(RM10.getMember(ten,q.member).name)}</strong><small>${E(RM10.getMember(ten,q.applicant).email)}</small><p>${E(q.response||q.note||L105('Kontak lama telah dikonfirmasi dalam simulasi.','Existing contact confirmed in this simulation.'))}</p></div><div><button class="btn" data-onboard105="claim-correct" data-id="${q.id}" data-version="${q.version||0}">${L105('Minta Perbaikan','Request Corrections')}</button><button class="btn primary" data-onboard105="claim-approve" data-id="${q.id}" data-version="${q.version||0}">${L105('Setujui Klaim','Approve Claim')}</button></div></article>`).join('')}</section>`:'');};labelsPage9=labels102;
const roleBefore105=role102;role102=function(role,id){onboarding105.active=false;onboarding105.document=false;if(role==='label'){const m=RM10.getMember(ten,id);if(m?.claimedLabel105)id=m.claimedLabel105;}return roleBefore105(role,id);};
const renderOnboard105=render;render=function(){renderOnboard105();if(onboarding105.document&&!document.querySelector('#dialog').open&&isLabel10()){onboarding105.document=false;queueMicrotask(()=>activationStep105());}if(onboarding105.bank&&!document.querySelector('#dialog').open){onboarding105.bank=false;queueMicrotask(submittedActivation105);}};
